import json
import re
import uuid
from pathlib import Path

import pytest
from base_e2e_test import BaseE2ETest
from flask import url_for
from htmx_helpers import reset_htmx_state, wait_for_htmx_settled, with_htmx_wait
from playwright.sync_api import Error, Page, expect

from tests.external_e2e import allow_requests_passthru
from tests.playwright.notification_helpers import dismiss_notifications


ASSESS_STORY_PAGE_SIZE = 20


@pytest.mark.e2e_user
@pytest.mark.e2e_ci
@pytest.mark.usefixtures("e2e_ci", "ensure_basic_user_permissions")
class TestEndToEndUser(BaseE2ETest):
    """End-to-end tests for the Taranis AI user interface."""

    CERT_REPORT_TYPE_LABEL = "CERT Report"
    ALL_ATTRIBUTE_REPORT_TYPE_LABEL = "Zzz_All Attribute Types Report"
    ALL_ATTRIBUTE_REQUIRED_REPORT_TYPE_LABEL = f"{ALL_ATTRIBUTE_REPORT_TYPE_LABEL} REQUIRED"

    @staticmethod
    def _get_assess_story_counts(page: Page) -> tuple[int, int]:
        story_count = page.get_by_test_id("assess_story_count")
        count_pattern = re.compile(r"(\d+)\s*/\s*(\d+)")
        expect(story_count).to_contain_text(count_pattern)
        count_text = story_count.inner_text()
        match = count_pattern.search(count_text)
        assert match, f"Unable to parse assess story count from: {count_text!r}"
        return int(match.group(1)), int(match.group(2))

    @staticmethod
    def _get_assess_selection_count(page: Page) -> int:
        count_text = page.get_by_test_id("assess_story_selection_count").inner_text()
        match = re.search(r"(\d+)\s+stories selected", count_text)
        assert match, f"Unable to parse assess story selection count from: {count_text!r}"
        return int(match.group(1))

    def test_login(self, taranis_frontend: Page):
        page = taranis_frontend
        page.context.clear_cookies()
        self.add_keystroke_overlay(page)

        page.goto(url_for("base.login", _external=True))
        expect(page).to_have_title("Taranis AI", timeout=5000)

        self.highlight_element(page.get_by_placeholder("Username"))
        page.get_by_placeholder("Username").fill("user")
        self.highlight_element(page.get_by_placeholder("Password"))
        page.get_by_placeholder("Password").fill("test")
        self.capture_screenshot(page, "./tests/playwright/screenshots/screenshot_login.png")
        self.highlight_element(page.get_by_test_id("login-button")).click()
        expect(page.locator("#dashboard")).to_be_visible()

    def test_admin_sidebar_collapsible_groups(self, admin_logged_in_page: Page):
        page = admin_logged_in_page
        page.goto(url_for("admin.attributes", _external=True))
        expect(page.get_by_test_id("admin-group-publishing-and-content-setup")).toBeVisible()
        details_locator = page.locator("details").filter(has=page.get_by_test_id("admin-menu-attributes"))
        expect(details_locator).toHaveAttribute("open", "")
        expect(page.get_by_test_id("admin-menu-users")).toBeVisible()
        expect(page.get_by_test_id("admin-menu-openapi")).toBeVisible()
