          <span>{{ group.name }}</span>
          {% if group_badge > 0 %}
            <span class="badge badge-sm badge-error ml-auto">{{ group_badge }}</span>
          {% endif %}
        </summary>
        <ul>
          {% for view_name in group.items %}
            {% if view_name in views_by_name %}
              {% set view = views_by_name[view_name] %}
              {% set badge = view.get_admin_menu_badge() if view.get_admin_menu_badge else 0 %}
              <li class="relative">
                <a href="{{ view.get_base_route() }}"
                   class="{% if badge > 0 and view.get_admin_menu_badge_route %}pr-12{% endif %} {% if request.path.startswith(view.get_base_route()) %}active{% endif %}"
                   data-testid="admin-menu-{{ view_name }}"
                   data-tour-target="admin-menu-{{ view_name | lower | replace(' ', '-') }}">
                  {{ heroicon_outline(view.icon) }}
                  {{ view_name }}
                </a>
                {% from "macros/admin_menu_badge.html" import admin_menu_badge %}
                {{ admin_menu_badge(view, view_name, badge) }}
              </li>
            {% endif %}
          {% endfor %}
        </ul>
      </details>
    </li>
  {% endfor %}

  <li>
    <a href="{{ url_for('base.open_api') }}" target="_blank">
